11480    else
 11481      {
 11482        /* If we are asked about a split dwarf (.dwo) file, use the user
 11483           provided, or find the corresponding skeleton file. If we got
 11484           a skeleton file, replace the given dwflmod and dbg, with one
 11485           derived from the skeleton file to provide enough context.  */
 11486        uint64_t split_id;
 11487        if (is_split_dwarf (dbg, &split_id, &split_cu))
 11488          {
 11489            if (dwarf_skeleton != NULL)
 11490              skel_name = strdup (dwarf_skeleton);
 11491            else
 11492              {
 11493                /* Replace file.dwo with file.o and see if that matches. */
 11494                const char *fname;
 11495                dwfl_module_info (dwflmod, NULL, NULL, NULL, NULL, NULL,
 11496                                  &fname, NULL);
 11497                if (fname != NULL)
 11498                  {
 11499                    size_t flen = strlen (fname);
 11500                    if (flen > 4 && strcmp (".dwo", fname + flen - 4) == 0)
 11501                      {
 11502                        skel_name = strdup (fname);
 11503                        if (skel_name != NULL)
 11504                          {
 11505                            skel_name[flen - 3] = 'o';
 11506                            skel_name[flen - 2] = '\0';
 11507                          }
 11508                      }
 11509                  }
 11510              }
 11511
 11512            if (skel_name != NULL)
 11513              {
 11514                int skel_fd = open (skel_name, O_RDONLY);
 11515                if (skel_fd == -1)
 11516                  fprintf (stderr, "Warning: Couldn't open DWARF skeleton file"
 11517                           " '%s'\n", skel_name);
 11518                else
 11519                  skel_dwfl = create_dwfl (skel_fd, skel_name);
 11520
 11521                if (skel_dwfl != NULL)
 11522                  {
 11523                    if (dwfl_getmodules (skel_dwfl, &getone_dwflmod,
 11524                                         &skel_mod, 0) != 0)
 11525                      {
 11526                        fprintf (stderr, "Warning: Bad DWARF skeleton,"
 11527                                 " multiple modules '%s'\n", skel_name);
 11528                        dwfl_end (skel_dwfl);
 11529                        skel_mod = NULL;
 11530                      }
 11531                  }
 11532                else if (skel_fd != -1)
 11533                  fprintf (stderr, "Warning: Couldn't create skeleton dwfl for"
 11534                           " '%s': %s\n", skel_name, dwfl_errmsg (-1));
 11535
 11536                if (skel_mod != NULL)
 11537                  {
 11538                    Dwarf *skel_dbg = dwfl_module_getdwarf (skel_mod, &dwbias);
 11539                    if (skel_dbg != NULL)
 11540                      {
 11541                        /* First check the skeleton CU DIE, only fetch
 11542                           the split DIE if we know the id matches to
 11543                           not unnecessary search for any split DIEs we
 11544                           don't need. */
 11545                        Dwarf_CU *cu = NULL;
 11546                        while (dwarf_get_units (skel_dbg, cu, &cu,
 11547                                                NULL, NULL, NULL, NULL) == 0)
 11548                          {
 11549                            uint8_t unit_type;
 11550                            uint64_t skel_id;
 11551                            if (dwarf_cu_info (cu, NULL, &unit_type, NULL, NULL,
 11552                                               &skel_id, NULL, NULL) == 0
 11553                                && unit_type == DW_UT_skeleton
 11554                                && split_id == skel_id)
 11555                              {
 11556                                Dwarf_Die subdie;
 11557                                if (dwarf_cu_info (cu, NULL, NULL, NULL,
 11558                                                   &subdie,
 11559                                                   NULL, NULL, NULL) == 0
 11560                                    && dwarf_tag (&subdie) != DW_TAG_invalid)
 11561                                  {
 11562                                    split_dbg = dwarf_cu_getdwarf (subdie.cu);
 11563                                    if (split_dbg == NULL)
 11564                                      fprintf (stderr,
 11565                                               "Warning: Couldn't get split_dbg:"
 11566                                               " %s\n", dwarf_errmsg (-1));
 11567                                    break;
 11568                                  }
 11569                                else
 11570                                  {
 11571                                    /* Everything matches up, but not
 11572                                       according to libdw. Which means
 11573                                       the user knew better.  So...
 11574                                       Terrible hack... We can never
 11575                                       destroy the underlying dwfl
 11576                                       because it would free the wrong
 11577                                       Dwarfs... So we leak memory...*/
 11578                                    if (cu->split == NULL
 11579                                        && dwarf_skeleton != NULL)
 11580                                      {
 11581                                        do_not_close_dwfl = true;
 11582                                        __libdw_link_skel_split (cu, split_cu);
 11583                                        split_dbg = dwarf_cu_getdwarf (split_cu);
 11584                                        break;
 11585                                      }
 11586                                    else
 11587                                      fprintf (stderr, "Warning: Couldn't get"
 11588                                               " skeleton subdie: %s\n",
 11589                                               dwarf_errmsg (-1));
 11590                                  }
 11591                              }
 11592                          }
 11593                        if (split_dbg == NULL)
 11594                          fprintf (stderr, "Warning: '%s' didn't contain a skeleton for split id %" PRIx64 "\n", skel_name, split_id);
 11595                      }
 11596                    else
 11597                      fprintf (stderr, "Warning: Couldn't get skeleton DWARF:"
 11598                               " %s\n", dwfl_errmsg (-1));
 11599                  }
 11600              }
 11601
 11602            if (split_dbg != NULL)
 11603              {
 11604                dbg = split_dbg;
 11605                dwflmod = skel_mod;
 11606              }
 11607            else if (skel_name == NULL)
 11608              fprintf (stderr,
 11609                       "Warning: split DWARF file, but no skeleton found.\n");
 11610          }
